\connect dmv_source
CREATE SCHEMA structure;
CREATE TABLE structure.same(id integer NOT NULL,label varchar(10) COLLATE "C" DEFAULT 'SYNTHETIC-DEFAULT-A',amount numeric(20,4),CONSTRAINT same_pk PRIMARY KEY(id),CONSTRAINT same_check CHECK(amount>=0));
CREATE INDEX same_label ON structure.same(label) INCLUDE(amount) WHERE id>0;
CREATE TABLE structure.column_type(value varchar(10),amount numeric(20,4));
CREATE TABLE structure.column_null(value integer NOT NULL);
CREATE TABLE structure.column_default(value text DEFAULT 'SYNTHETIC-PRIVATE-DEFAULT-A');
CREATE TABLE structure.column_identity(value integer GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE structure.column_generated(value integer,derived integer GENERATED ALWAYS AS (value+1) STORED);
CREATE TABLE structure.column_storage(value text);
CREATE TABLE structure.column_compression(value text COMPRESSION pglz);
CREATE TABLE structure.column_statistics(value integer);
CREATE TABLE structure.column_collation(value text COLLATE "C");
CREATE TABLE structure.parent_keys(a integer,b integer,PRIMARY KEY(a,b));
CREATE TABLE structure.fk_action(a integer,b integer,CONSTRAINT fk FOREIGN KEY(a,b) REFERENCES structure.parent_keys(a,b) ON DELETE CASCADE);
CREATE TABLE structure.fk_deferred(a integer,b integer,CONSTRAINT fk FOREIGN KEY(a,b) REFERENCES structure.parent_keys(a,b));
CREATE TABLE structure.fk_initial(a integer,b integer,CONSTRAINT fk FOREIGN KEY(a,b) REFERENCES structure.parent_keys(a,b) DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE structure.check_definition(value integer,CONSTRAINT c CHECK(value>=0));
CREATE TABLE structure.check_validated(value integer);
ALTER TABLE structure.check_validated ADD CONSTRAINT c CHECK(value>=0) NOT VALID;
CREATE TABLE structure.constraint_missing(value integer,CONSTRAINT c CHECK(value>=0));
CREATE TABLE structure.exclusion(period int4range,CONSTRAINT x EXCLUDE USING gist(period WITH &&));
CREATE TABLE structure.index_key(a integer,b integer);
CREATE INDEX x_key ON structure.index_key(a,b);
CREATE TABLE structure.index_include(a integer,b integer);
CREATE INDEX x_include ON structure.index_include(a) INCLUDE(b);
CREATE TABLE structure.index_predicate(a integer);
CREATE INDEX x_predicate ON structure.index_predicate(a) WHERE a>0;
CREATE TABLE structure.index_expression(value text);
CREATE INDEX x_expression ON structure.index_expression(lower(value));
CREATE TABLE structure.index_unique(a integer);
CREATE INDEX x_unique ON structure.index_unique(a);
CREATE TABLE structure.index_nulls(a integer);
CREATE UNIQUE INDEX x_nulls ON structure.index_nulls(a);
CREATE TABLE structure.index_method(a integer);
CREATE INDEX x_method ON structure.index_method USING btree(a);
CREATE TABLE structure.index_options(a integer);
CREATE INDEX x_options ON structure.index_options(a) WITH(fillfactor=90);
CREATE TABLE structure.replica(a integer NOT NULL);
CREATE UNIQUE INDEX x_replica ON structure.replica(a);
CREATE UNLOGGED TABLE structure.persistence(value integer);
CREATE TABLE structure.partitioned(id integer) PARTITION BY RANGE(id);
CREATE TABLE structure.partition_mid PARTITION OF structure.partitioned FOR VALUES FROM(0) TO(100) PARTITION BY RANGE(id);
CREATE TABLE structure.partition_leaf PARTITION OF structure.partition_mid FOR VALUES FROM(0) TO(10);
CREATE TABLE structure.inheritance_parent(value integer);
CREATE TABLE structure.inheritance_child() INHERITS(structure.inheritance_parent);
CREATE EXTENSION postgres_fdw;
CREATE SERVER fixture_foreign FOREIGN DATA WRAPPER postgres_fdw OPTIONS(dbname 'nonexistent');
CREATE FOREIGN TABLE structure.foreign_observed(value integer) SERVER fixture_foreign;
