ALTER TABLE structure.column_type ALTER COLUMN value TYPE varchar(11),ALTER COLUMN amount TYPE numeric(21,5);
ALTER TABLE structure.column_null ALTER COLUMN value DROP NOT NULL;
ALTER TABLE structure.column_default ALTER COLUMN value SET DEFAULT 'SYNTHETIC-PRIVATE-DEFAULT-B';
ALTER TABLE structure.column_identity ALTER COLUMN value SET GENERATED ALWAYS;
ALTER TABLE structure.column_generated DROP COLUMN derived;
ALTER TABLE structure.column_generated ADD COLUMN derived integer GENERATED ALWAYS AS(value+2) STORED;
ALTER TABLE structure.column_storage ALTER COLUMN value SET STORAGE EXTERNAL;
ALTER TABLE structure.column_compression ALTER COLUMN value SET COMPRESSION lz4;
ALTER TABLE structure.column_statistics ALTER COLUMN value SET STATISTICS 200;
ALTER TABLE structure.column_collation ALTER COLUMN value TYPE text COLLATE "POSIX";
ALTER TABLE structure.fk_action DROP CONSTRAINT fk;
ALTER TABLE structure.fk_action ADD CONSTRAINT fk FOREIGN KEY(a,b) REFERENCES structure.parent_keys(a,b) ON DELETE RESTRICT;
ALTER TABLE structure.fk_deferred ALTER CONSTRAINT fk DEFERRABLE;
ALTER TABLE structure.fk_initial ALTER CONSTRAINT fk INITIALLY DEFERRED;
ALTER TABLE structure.check_definition DROP CONSTRAINT c;
ALTER TABLE structure.check_definition ADD CONSTRAINT c CHECK(value>=1);
ALTER TABLE structure.check_validated VALIDATE CONSTRAINT c;
ALTER TABLE structure.constraint_missing DROP CONSTRAINT c;
ALTER TABLE structure.exclusion DROP CONSTRAINT x;
ALTER TABLE structure.exclusion ADD CONSTRAINT x EXCLUDE USING gist(period WITH &&) DEFERRABLE;
DROP INDEX structure.x_key;
CREATE INDEX x_key ON structure.index_key(b,a);
DROP INDEX structure.x_include;
CREATE INDEX x_include ON structure.index_include(a);
DROP INDEX structure.x_predicate;
CREATE INDEX x_predicate ON structure.index_predicate(a) WHERE a>1;
DROP INDEX structure.x_expression;
CREATE INDEX x_expression ON structure.index_expression(upper(value));
DROP INDEX structure.x_unique;
CREATE UNIQUE INDEX x_unique ON structure.index_unique(a);
DROP INDEX structure.x_nulls;
CREATE UNIQUE INDEX x_nulls ON structure.index_nulls(a) NULLS NOT DISTINCT;
DROP INDEX structure.x_method;
CREATE INDEX x_method ON structure.index_method USING hash(a);
ALTER INDEX structure.x_options SET(fillfactor=80);
ALTER TABLE structure.replica REPLICA IDENTITY USING INDEX x_replica;
ALTER TABLE structure.persistence SET LOGGED;
DROP TABLE structure.partition_leaf;
CREATE TABLE structure.partition_leaf PARTITION OF structure.partition_mid FOR VALUES FROM(0) TO(11);
ALTER TABLE structure.inheritance_child NO INHERIT structure.inheritance_parent;
